const $=id=>document.getElementById(id),esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let page=1;
const table=(headers,rows)=>`<table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
async function load(){try{$('status').textContent='Carregando…';const r=await fetch(`/api/admin?page=${page}&q=${encodeURIComponent($('query').value)}`);if(!r.ok)throw new Error(r.status===403?'Conta sem acesso administrativo.':r.status===401?'Faça login no jogo antes de entrar no admin.':'Falha ao consultar os dados.');const data=await r.json();$('totals').innerHTML=Object.entries(data.totals).map(([k,v])=>`<span>${({accounts:'Contas',sessions:'Sessões',listings:'Anúncios ativos',items:'Itens'})[k]}: <b>${v}</b></span>`).join('');$('accounts').innerHTML=table(['Usuário','ID da conta','Capítulo','Herói padrão','Gold','Cadastro'],data.accounts.map(a=>[a.username,a.id,a.unlocked_chapter,a.preferred_hero,a.gold,new Date(a.created_at).toLocaleString('pt-BR')]));$('sessions').innerHTML=table(['Usuário','Última atividade','Expira em'],data.sessions.map(s=>[s.username,s.last_seen?new Date(s.last_seen).toLocaleString('pt-BR'):'Sem atividade recente',new Date(s.expires_at).toLocaleString('pt-BR')]));$('page').textContent=`Página ${page}`;$('prev').disabled=page===1;$('next').disabled=data.accounts.length<20;$('status').textContent='';}catch(e){$('status').textContent=e.message;}}
$('search').onsubmit=e=>{e.preventDefault();page=1;void load();};$('prev').onclick=()=>{page--;void load();};$('next').onclick=()=>{page++;void load();};void load();
